final_validate_smoke_run <- function(inventory, expected_dates, weekly_result, template_path) {
  if (isTRUE(getOption("cdsdatagrab.dry_run_plan", FALSE))) return(list(status="success", reason="dry_run_plan_valid", expected_observed_dates=length(unique(as.Date(expected_dates))), valid_observed_daily_products=NA_integer_, invalid_daily_products=NA_integer_, missing_expected_dates=character(), duplicate_observed_dates=0L, weekly_outputs_written=0L, weekly_outputs_reused=0L, weekly_outputs_replaced=0L, incomplete_weeks=0L))
  expected<-sort(unique(as.Date(expected_dates)));valid<-inventory$observed_valid%in%TRUE;dates<-sort(unique(inventory$date[valid&!inventory$estimated]));invalid<-inventory[!valid&!inventory$estimated,,drop=FALSE];missing<-setdiff(expected,dates);duplicates<-dates[duplicated(dates)];if(length(missing)||nrow(invalid)||length(duplicates))stop("Final validation failed: daily coverage is incomplete or invalid",call.=FALSE);list(status="success",expected_observed_dates=length(expected),valid_observed_daily_products=sum(valid&!inventory$estimated),invalid_daily_products=nrow(invalid),missing_expected_dates=as.character(missing),duplicate_observed_dates=length(duplicates),weekly_outputs_written=length(weekly_result$written%||%character()),weekly_outputs_reused=length(weekly_result$reused%||%character()),weekly_outputs_replaced=length(weekly_result$replaced%||%character()),incomplete_weeks=nrow(weekly_result$incomplete_weeks%||%data.frame()))
}

run_era5_mintemp_pipeline <- function(config_path="config/era5_mintemp.yml",mode=c("diagnose","plan","download","process","aggregate","estimate","full"),dry_run=TRUE,observed_end=NULL,future_end=NULL,start_date=NULL,end_date=NULL,output_root=NULL,overwrite=FALSE,rebuild_all_weeks=FALSE,execution_source="default",transfer_fun=NULL) {
