    raw_all<-if(dir.exists(storage$raw_dir))list.files(storage$raw_dir,full.names=TRUE,pattern="\\.(nc|netcdf|nc4|zip|grib)$",ignore.case=TRUE)else character();active_req<-if(length(req))req else build_variable_requests(expected,area,cfg,spec);sel<-select_active_raw_inputs(active_req,dl,raw_all);m$active_raw_inputs<-sel$active;m$reused_matching_raw_inputs<-sel$reused_matching;m$unmatched_raw_inputs<-sel$unmatched;m$superseded_raw_inputs<-sel$superseded;m$invalid_raw_inputs<-sel$invalid;m$date_source_map<-map_dates_to_active_raw_sources(sel$active,active_req);m$active_request_hashes<-if(length(sel$active)&&length(active_req))vapply(active_req,function(x)x$request_hash,character(1))else character()
    if(mode%in%c("process","full")&&!dry_run){required_dates<-sort(unique(as.Date(expected)));existing_valid_dates<-sort(unique(inv_before$date[isTRUE(inv_before$observed_valid)|(!is.na(inv_before$observed_valid)&inv_before$observed_valid)&!inv_before$estimated]));dates_still_needed<-setdiff(required_dates,existing_valid_dates);mapped_dates<-if(nrow(m$date_source_map))sort(unique(as.Date(m$date_source_map$date)))else as.Date(character());unmapped<-setdiff(dates_still_needed,mapped_dates);m$process_stage_invariants<-list(required_dates=as.character(required_dates),existing_valid_dates=as.character(existing_valid_dates),dates_still_needed=as.character(dates_still_needed),mapped_dates=as.character(mapped_dates),unmapped=as.character(unmapped));if(length(unmapped))stop(paste0("pipeline_status=failed\nfailed_stage=process\nreason=required_dates_unmapped\nunmapped_dates=",paste(format(unmapped),collapse=","),"\nactive_raw_candidates=",paste(basename(sel$active),collapse=",")),call.=FALSE);m<-update_manifest_stage(m,"process","running");pr<-process_downloaded_variable(sel$active,storage$daily_dir,cfg$spatial$template_path,cfg$spatial$bbox_path,cfg,spec,overwrite_dates=if(overwrite)expected else NULL,run_expected_dates=expected,request_manifest=active_req,date_source_map=m$date_source_map,run_dir=m$run_dir);m$daily_outputs_written<-length(pr$written);m$daily_outputs_reused<-length(pr$reused);m$daily_outputs_replaced<-length(pr$replaced);m$daily_outputs_failed<-length(pr$failed);m$processing_failures<-pr$processing_failures%||%list();if(!is.null(pr$date_source_map))m$date_source_map<-pr$date_source_map;m<-update_manifest_stage(m,"process","running",list(result=pr,processing_failures=m$processing_failures));if(length(m$processing_failures)){f<-m$processing_failures[[1]];log_stage(storage,m$run_id,"process","failed",c(paste0("raw_path=",f$raw_path),paste0("date=",f$date),paste0("processing_step=",f$processing_step),paste0("error_class=",f$error_class),paste0("error_message=",g