    inv_after<-inventory_daily_products(storage$daily_dir,spec$daily_filename_prefix,cfg$spatial$template_path,TRUE,cfg);m$daily_inventory_after_process<-inv_after;m$daily_products_valid<-sum(inv_after$observed_valid,na.rm=TRUE);m$daily_products_invalid<-sum(!inv_after$observed_valid&!inv_after$estimated,na.rm=TRUE);m$valid_observed_dates<-as.character(sort(unique(inv_after$date[inv_after$observed_valid&!inv_after$estimated])));m$invalid_observed_dates<-as.character(sort(unique(inv_after$date[!inv_after$observed_valid&!inv_after$estimated])))
    weekly_result<-list(status="success_noop",written=character(),reused=character(),replaced=character(),incomplete_weeks=data.frame(),affected_iso_weeks=character());if(mode%in%c("aggregate","full")&&!dry_run){m<-update_manifest_stage(m,"aggregate","running");weekly_result<-aggregate_daily_to_weekly(storage$daily_dir,storage$weekly_dir,spec$weekly_filename_prefix,overwrite=TRUE,template_path=cfg$spatial$template_path,rebuild_all=rebuild_all_weeks,inventory=inv_after,inventory_source="post_process",variable_spec=spec,config=cfg);m$aggregation_inventory_source<-weekly_result$inventory_source;m$aggregation_valid_daily_dates_received<-weekly_result$valid_daily_dates_received;m$aggregation_expected_dates<-weekly_result$expected_dates;m$aggregation_match_counts<-weekly_result$match_counts;m$aggregation_selected_daily_paths<-weekly_result$selected_daily_paths;m$affected_iso_weeks<-weekly_result$affected_iso_weeks%||%character();m$incomplete_iso_weeks<-weekly_result$incomplete_weeks$week_id%||%character();m$complete_iso_weeks<-weekly_result$complete_weeks%||%character();m$weekly_outputs_written<-length(weekly_result$written);m$weekly_outputs_reused<-length(weekly_result$reused);m$weekly_outputs_replaced<-length(weekly_result$replaced);m<-update_manifest_stage(m,"aggregate",weekly_result$status,list(result=weekly_result));log_stage(storage,m$run_id,"aggregate",weekly_result$status,paste0("affected_iso_weeks=",length(m$affected_iso_weeks)))}else if(mode%in%c("aggregate","full"))m<-update_manifest_stage(m,"aggregate","not_run")
